"use strict";(()=>{var MEMORY_KEY="moai.web";var normalizeTheme=value=>value==="light"||value==="dark"?value:"system";function applyTheme(doc,theme){let root=doc.documentElement;theme==="system"?delete root.dataset.theme:root.dataset.theme=theme}function storedTheme(key,backend){try{let text=backend()?.getItem(key);return text?normalizeTheme(JSON.parse(text)?.theme):"system"}catch{return"system"}}applyTheme(document,storedTheme(MEMORY_KEY,()=>window.localStorage));})();
